args.content:
# A20: the fallback state directory must be anchored at the workspace, not at the CWD.
$ErrorActionPreference = 'Stop'
$cli = '{cliExe}'
if (-not (Test-Path -LiteralPath $cli)) { Write-Output 'ANCHOR ERROR cli-missing'; exit 0 }
$ws = (Get-Location).Path
# Precondition: `.b4scratch` is what the anchor keys on. An agent workspace always has it
# (TEMP/APPDATA point into it); create it so the probe is self-contained.
New-Item -ItemType Directory -Force (Join-Path $ws '.b4scratch') | Out-Null
# With the variable gone the CLI has to derive the fallback itself, which is the path the
# 18-minute run took when it lost its session.
Remove-Item Env:BROWSER4_CLI_STATE_DIR -ErrorAction SilentlyContinue
$dirs = @()
foreach ($sub in @('anchor-sub-one', 'anchor-sub-two')) {
    $dir = Join-Path $ws $sub
    New-Item -ItemType Directory -Force $dir | Out-Null
    Push-Location $dir
    try {
        $raw = & $cli status --json 2>$null | Out-String
        $dirs += [string](($raw | ConvertFrom-Json).output.session_state_dir)
    } catch {
        Write-Output ('ANCHOR ERROR status-failed sub=' + $sub)
        exit 0
    } finally {
        Pop-Location
    }
}
if ($dirs.Count -ne 2 -or -not $dirs[0] -or -not $dirs[1]) { Write-Output 'ANCHOR ERROR no-state-dir'; exit 0 }
if ($dirs[0] -ne $dirs[1]) { Write-Output ('ANCHOR MISMATCH one=' + $dirs[0] + ' two=' + $dirs[1]); exit 0 }
if (-not $dirs[0].EndsWith('.b4scratch\cli-state')) { Write-Output ('ANCHOR NOT-ANCHORED ' + $dirs[0]); exit 0 }
Write-Output ('ANCHOR OK ' + $dirs[0])
